const items = $input.all();

if (items.length === 0) {
  return [{ json: { mensaje: 'No hay clientes escalados', cantidad: 0 } }];
}
// Agrupar por prioridad
const porPrioridad = {
  urgente: [],
  alta: [],
  normal: []
};

items.forEach(item => {
  const p = item.json.prioridad_escalado || 'normal';
  if (!porPrioridad[p]) porPrioridad[p] = [];
  porPrioridad[p].push(item.json);
});

// Analizar SLA
const sla = {
  urgente: 15,
  alta: 30,
  normal: 60
};

const excedidos = {
  urgente: porPrioridad.urgente.filter(i => i.minutos_esperando > sla.urgente),
  alta: porPrioridad.alta.filter(i => i.minutos_esperando > sla.alta),
  normal: porPrioridad.normal.filter(i => i.minutos_esperando > sla.normal)
};

// Determinar nivel de alerta
let alerta = '';
if (excedidos.urgente.length > 0) {
  alerta = '🚨 CRÍTICO';
} else if (excedidos.alta.length > 0) {
  alerta = '⚠️ ALERTA';
} else if (excedidos.normal.length > 0) {
  alerta = '📋 RECORDATORIO';
} else {
  alerta = '✅ EN SLA';
}

// Preparar mensaje
let mensaje = `${alerta} CLIENTES ESCALADOS\n\n`;

if (porPrioridad.urgente.length > 0) {
  mensaje += `🔴 URGENTE (${porPrioridad.urgente.length}):\n`;
  porPrioridad.urgente.forEach((i, idx) => {
    const sla_status = i.minutos_esperando > sla.urgente ? '❌ SLA EXCEDIDO' : '✅';
    mensaje += `  ${idx + 1}. *${i.nombre || 'Sin nombre'}*\n`;
    mensaje += `     📱 ${i.telefono}\n`;
    mensaje += `     ⏱️ ${Math.floor(i.minutos_esperando)} min ${sla_status}\n`;
    mensaje += `     📝 ${i.motivo_escalado || 'Sin motivo'}\n`;
  });
}

if (porPrioridad.alta.length > 0) {
  mensaje += `\n🟡 ALTA (${porPrioridad.alta.length}):\n`;
  porPrioridad.alta.forEach((i, idx) => {
    const sla_status = i.minutos_esperando > sla.alta ? '❌ SLA EXCEDIDO' : '✅';
    mensaje += `  ${idx + 1}. *${i.nombre || 'Sin nombre'}*\n`;
    mensaje += `     📱 ${i.telefono}\n`;
    mensaje += `     ⏱️ ${Math.floor(i.minutos_esperando)} min ${sla_status}\n`;
  });
}

if (porPrioridad.normal.length > 0) {
  mensaje += `\n🟢 NORMAL (${porPrioridad.normal.length}):\n`;
  porPrioridad.normal.forEach((i, idx) => {
    const sla_status = i.minutos_esperando > sla.normal ? '❌ SLA EXCEDIDO' : '✅';
    mensaje += `  ${idx + 1}. *${i.nombre || 'Sin nombre'}*\n`;
    mensaje += `     📱 ${i.telefono}\n`;
    mensaje += `     ⏱️ ${Math.floor(i.minutos_esperando)} min ${sla_status}\n`;
  });
}

// Resumen
const totalEscalados = items.length;
const totalExcedidos = excedidos.urgente.length + excedidos.alta.length + excedidos.normal.length;

mensaje += `\n📊 RESUMEN:\n`;
mensaje += `• Total: ${totalEscalados}\n`;
mensaje += `• SLA excedidos: ${totalExcedidos}\n`;
mensaje += `• En tiempo: ${totalEscalados - totalExcedidos}\n`;

if (totalExcedidos > 0) {
  mensaje += `\n⚠️ NECESITA ATENCIÓN INMEDIATA: ${totalExcedidos} cliente(s) fuera de SLA`;
}

// Lista de teléfonos para marcar como notificados
const telefonos = items.map(i => i.json.telefono);

return [{
  json: {
    mensaje,
    telefonos,
    cantidad: totalEscalados,
    excedidos: totalExcedidos,
    alerta_nivel: alerta,
    por_prioridad: {
      urgente: porPrioridad.urgente.length,
      alta: porPrioridad.alta.length,
      normal: porPrioridad.normal.length
    }
  }
}];

const datos = $('📝 Preparar Mensaje SLA').first().json;

const mensajeReporte = `
📊 ACTUALIZACIÓN ESCALADOS

${datos.alerta_nivel}

📌 Por Prioridad:
• Urgentes: ${datos.por_prioridad.urgente}
• Altos: ${datos.por_prioridad.alta}
• Normales: ${datos.por_prioridad.normal}

📈 SLA:
• Total: ${datos.cantidad}
• En tiempo: ${datos.cantidad - datos.excedidos}
• Excedidos: ${datos.excedidos}
`;

return [{
  json: {
    mensaje: mensajeReporte,
    timestamp: new Date().toISOString()
  }
}];
